<template>
 <section class="ped"><header class="head"><div><h1>Gestión de Pedidos</h1><p class="muted">Solicitudes de abastecimiento por ubicación. El registro no modifica existencias.</p></div><RouterLink class="btn primary" to="/pedidos/crear">+ Nuevo pedido</RouterLink></header>
 <div v-if="seguimiento" class="panel seguimiento"><div class="seg-head"><div><h2>Seguimiento del pedido #{{ seguimiento.pedido.id_pedido }}</h2><p class="muted">Cantidades solicitadas, despachadas, en tránsito y recibidas.</p></div><button class="btn small" @click="seguimiento=null">Cerrar</button></div>
 <div class="tablewrap"><table><thead><tr><th>Presentación</th><th>Solicitado</th><th>Despachado</th><th>En tránsito</th><th>Recibido</th><th>Diferencia observada</th><th>Pendiente de despacho</th></tr></thead><tbody><tr v-for="l in seguimiento.lineas" :key="l.id_presentacion"><td>{{l.presentacion?.producto?.nombre}} · {{l.presentacion?.nombre_presentacion}}</td><td>{{l.solicitado}}</td><td>{{l.despachado}}</td><td>{{l.en_transito}}</td><td>{{l.recibido}}</td><td :class="{'alerta':l.diferencia_observada>0}">{{l.diferencia_observada}}</td><td>{{l.pendiente_despacho}}</td></tr></tbody></table></div>
 <h3>Despachos relacionados</h3><p v-if="!seguimiento.movimientos.length" class="muted">Aún no se registraron despachos.</p><div v-for="m in seguimiento.movimientos" :key="m.id_movimiento" class="seg-mov">Transferencia #{{m.id_movimiento}} · {{m.estado_recepcion || 'Sin estado'}} · {{fecha(m.fecha_movimiento)}}</div>
 <p class="muted">Las diferencias observadas requieren revisión administrativa; no se incorporan al stock del destino.</p></div>
 <div class="panel"><div class="toolbar"><input v-model="buscar" placeholder="Buscar por observación" @keyup.enter="cargar(1)"><select v-model="estado" @change="cargar(1)"><option value="">Todos los estados</option><option value="PENDIENTE">Pendiente</option><option value="APROBADO">Aprobado</option><option value="RECHAZADO">Rechazado</option><option value="ATENDIDO">Atendido</option></select><select v-model.number="limit" @change="cargar(1)"><option :value="10">10 registros</option><option :value="25">25 registros</option><option :value="50">50 registros</option></select><button class="btn" @click="cargar(1)">Buscar</button></div>
 <div v-if="error" class="error">{{ error }}</div><div class="tablewrap"><table><thead><tr><th>ID</th><th>Fecha</th><th>Solicitante</th><th>Tipo</th><th>Estado</th><th>Detalles</th><th>Acciones</th></tr></thead><tbody><tr v-for="p in pedidos" :key="p.id_pedido"><td>#{{p.id_pedido}}</td><td>{{fecha(p.fecha_pedido)}}</td><td>{{p.ubicacion_solicitante?.nombre || p.ubicacion_solicitante?.nombre_ubicacion || '—'}}</td><td>{{p.tipo}}</td><td><span class="pill">{{p.estado}}</span></td><td>{{p.detalles?.length || 0}}</td><td><div class="actions"><RouterLink class="btn small" :to="`/pedidos/${p.id_pedido}`">Detalle</RouterLink><RouterLink v-if="p.estado==='PENDIENTE'" class="btn small" :to="`/pedidos/editar/${p.id_pedido}`">Editar</RouterLink><button class="btn small" @click="verSeguimiento(p)">Seguimiento</button><button v-if="p.estado==='PENDIENTE'" class="btn small danger" @click="eliminar(p)">Eliminar</button></div></td></tr><tr v-if="!cargando && !pedidos.length"><td colspan="7">No hay pedidos registrados para estos filtros.</td></tr></tbody></table></div>
 <div class="rowactions"><span class="muted">Página {{pagina}} de {{ultima}} · {{total}} registros</span><button class="btn small" :disabled="pagina<=1 || cargando" @click="cargar(pagina-1)">Anterior</button><button class="btn small" :disabled="pagina>=ultima || cargando" @click="cargar(pagina+1)">Siguiente</button></div></div></section>
</template>
<script>
import api from '../../services/api';
export default {data(){return {pedidos:[],buscar:'',estado:'',limit:10,pagina:1,ultima:1,total:0,cargando:false,error:'',seguimiento:null}},mounted(){this.cargar(1)},methods:{async verSeguimiento(p){this.error='';try{const {data}=await api.get(`/api/pedidos/${p.id_pedido}/seguimiento`);this.seguimiento=data}catch(e){this.error=e.response?.data?.message||'No se pudo consultar el seguimiento.'}},fecha(v){return v?new Date(v).toLocaleDateString('es-BO'):'—'},async cargar(p){this.cargando=true;this.error='';try{const {data}=await api.get('/api/pedidos',{params:{page:p,limit:this.limit,buscar:this.buscar,estado:this.estado}});this.pedidos=data.data||[];this.pagina=data.current_page||1;this.ultima=data.last_page||1;this.total=data.total||0}catch(e){this.error=e.response?.data?.message||'No se pudieron cargar los pedidos.'}finally{this.cargando=false}},async eliminar(p){if(!confirm(`¿Eliminar el pedido #${p.id_pedido}? Solo es posible si está pendiente.`))return;try{await api.delete(`/api/pedidos/${p.id_pedido}`);await this.cargar(this.pagina)}catch(e){alert(e.response?.data?.message||'No se pudo eliminar el pedido.')}}}}
</script>
<style scoped>
.ped{padding:24px;max-width:1450px;margin:auto;color:#103a2d}.head{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:22px}.head h1{font-size:30px;margin:0;color:#0c3025}.muted{color:#61756c;font-size:14px}.panel{background:#fff;border:1px solid #dbe7df;border-radius:16px;padding:24px;box-shadow:0 8px 24px #103a2d0b;margin-bottom:18px}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:18px}.toolbar>*{flex:1;min-width:150px}input,select,textarea{width:100%;min-height:42px;border:1px solid #cbded2;border-radius:9px;padding:10px;background:white;color:#183b2e;font:inherit}textarea{min-height:88px}label{font-size:13px;font-weight:700;display:block;margin-bottom:7px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}.btn{border:1px solid #cbded2;border-radius:9px;padding:11px 16px;cursor:pointer;background:#fff;color:#124734;font-weight:700}.btn:hover{filter:brightness(.96)}.primary{background:#f47b20;color:#fff;border-color:#f47b20}.danger{background:#fff0ee;color:#a72c2c;border-color:#f3cccc}.small{padding:7px 10px;font-size:12px}.btn:disabled{opacity:.5;cursor:not-allowed}.actions{display:flex;gap:8px;flex-wrap:wrap}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:14px}th{background:#0c3025;color:white;text-align:left;padding:13px}td{border-bottom:1px solid #e0e9e3;padding:12px;vertical-align:middle}.error{color:#a52d2d;background:#fff0ee;border-radius:8px;padding:12px;margin-bottom:15px}.pill{background:#eaf4ee;color:#0b5c3a;border-radius:20px;padding:5px 10px;font-weight:700;font-size:12px}.rowactions{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}@media(max-width:720px){.grid{grid-template-columns:1fr}.ped{padding:12px}.panel{padding:15px}.head h1{font-size:24px}}
</style>
<style scoped>.seguimiento{border-left:5px solid #f47b20}.seg-head{display:flex;justify-content:space-between;gap:15px;align-items:center}.seg-head h2{margin:0;color:#124734}.seg-mov{background:#f4f8f5;border:1px solid #dce8df;border-radius:9px;padding:12px;margin:8px 0}.alerta{color:#b54b12;font-weight:800}</style>
